(()=>{'use strict';
const $=s=>document.querySelector(s),app=$('#app'),nav=$('#navigation'),key='velo-design-v1';
const center={lat:33.551833,lon:133.507556},groups=['常用','补水','休息','维修','风景','其他'],colors=['#2d5be3','#238a74','#ba7d24','#a45fb6'];
const samples=[{id:'sample-river',name:'河畔休息点（示例）',group:'休息',note:'路线与设施信息仅用于原型演示。',lat:33.5531,lon:133.5063,color:colors[1]},{id:'sample-water',name:'沿河补水点（示例）',group:'补水',note:'请在正式应用中核对地点与营业情况。',lat:33.5506,lon:133.5100,color:colors[0]},{id:'sample-home',name:'家（示例）',group:'常用',note:'编辑为你自己的位置。',lat:33.5504,lon:133.5072,color:colors[2]}];
let store={favorites:structuredClone(samples),routes:[],rides:[]};try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.favorites)&&Array.isArray(saved.routes)&&Array.isArray(saved.rides))store=saved;}catch{}
let state={page:'map',selected:null,filter:'全部',query:'',routeFilter:'saved',searchTarget:'destination',draft:{from:{...center,name:'当前位置（示例）'},to:null,via:[]},ready:false,connected:false,showPins:true,alert:true,boardRoads:true,editing:null,editorReturn:'favorites',paused:false,wrong:false};let toastTimer,undo=null;
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>globalThis.crypto?.randomUUID?.()||'p-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const favorite=p=>p&&store.favorites.find(x=>x.id===p.id);
const glyph=p=>p.group==='补水'?'water':p.group==='常用'?'home':'pin';
const point=p=>[210+(p.lon-center.lon)*Math.cos(center.lat*Math.PI/180)*111195*.55,360-(p.lat-center.lat)*111195*.55];
function persist(){try{localStorage.setItem(key,JSON.stringify(store));return true;}catch{toast('当前浏览器不能保存数据，请导出备份。');return false;}}
function toast(message,canUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${esc(message)}</span>${canUndo?'<button data-act="undo">撤销</button>':''}`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),canUndo?7000:4000);}
function row(p){return `<button class="place-row" data-act="place" data-id="${esc(p.id)}"><span class="place-icon" style="color:${esc(p.color||colors[0])}">${icon(glyph(p))}</span><span class="content"><strong>${esc(p.name)}</strong><small>${esc(p.group||'地点')} · ${p.lat.toFixed(5)}, ${p.lon.toFixed(5)}</small>${p.note?`<small>${esc(p.note)}</small>`:''}</span><span class="chevron">›</span></button>`;}
function empty(title,description,button,action){return `<div class="empty">${icon('pin')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${button?`<button class="primary block" data-act="${action}">${esc(button)}</button>`:''}</div>`;}
function head(title,action='',label=''){return `<header class="screen-head"><h1>${title}</h1>${action?`<button class="text-action" data-act="${action}">${label}</button>`:''}</header>`;}
function go(page){state.page=page;state.selected=null;state.query='';if(page!=='search')state.searchTarget='destination';render();}
function selectPlace(p){if(!p)return;state.selected={...p};state.page='detail';state.query='';render();}
function roads(){return `<g>${(window.VELO_ROADS||[]).map(r=>`<path d="${r.d}" class="road-casing"/><path d="${r.d}" class="road-main ${r.k===2?'road-major':r.k===0?'road-path':''}"/>`).join('')}</g>`;}
const roadsMarkup=roads();
function mapBase(route=false){
 let pins=state.showPins?store.favorites.map(p=>{const[x,y]=point(p);return `<g class="map-marker" data-act="map-pin" data-id="${esc(p.id)}" transform="translate(${x},${y})"><circle r="17"/><text y="1">${p.group==='补水'?'•':'☆'}</text></g>`;}).join(''):'';
 const selected=state.selected;if(selected&&!favorite(selected)){let[x,y]=point(selected);pins+=`<g transform="translate(${x},${y})"><circle r="18" fill="var(--accent)" stroke="var(--bg)" stroke-width="4"/><circle r="4" fill="var(--bg)"/></g>`;}
 const pts=[state.draft.from,...state.draft.via,state.draft.to].filter(Boolean).map(point),routePath=pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');
 const r=route&&state.ready?`<path d="${routePath}" class="route-outline"/><path d="${routePath}" class="route-line"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="10" fill="var(--accent)" stroke="var(--bg)" stroke-width="3"/><text x="${p[0]}" y="${p[1]+4}" fill="var(--bg)" font-size="11" text-anchor="middle">${i+1}</text>`).join('')}`:'';
 return `<div class="map-stage"><svg id="map-canvas" class="map-svg" viewBox="0 0 420 740" aria-label="高知附近实际道路，地点为示例">${roadsMarkup}${r}${pins}<circle cx="210" cy="360" r="27" class="position-ring"/><circle cx="210" cy="360" r="7" class="position-dot"/></svg><span class="map-credit">道路 © OpenStreetMap · 地点与路线为原型示例</span></div>`;
}
function deviceChip(){return `<button class="device-chip" data-act="device"><span class="status-dot ${state.connected?'on':''}"></span>${state.connected?'码表已连接 · 演示':'码表待连接'}　›</button>`;}
function mapTools(){return `<div class="map-controls"><button class="icon-btn" aria-label="回到当前位置" data-act="locate">${icon('target')}</button><button class="icon-btn" aria-label="显示或隐藏收藏" aria-pressed="${state.showPins}" data-act="layers">${icon('layers')}</button><button class="icon-btn" aria-label="地图中心标点" data-act="drop">${icon('pin')}</button></div>`;}
function mapPage(){return `${mapBase()}<div class="map-top"><button class="search-launch" data-act="search">${icon('search')}<span class="placeholder">搜索地点、地址或坐标</span><span class="avatar">V</span></button>${deviceChip()}</div>${mapTools()}<section class="sheet map-home-sheet"><div class="sheet-grip"></div><h2>想骑到哪里？</h2><p class="sub">从收藏出发，或在地图上选一个地方。</p><button class="primary block" data-act="search">${icon('search')}查找目的地</button><div class="quick-list">${store.favorites.slice(0,3).map(p=>`<button class="quick-item" data-act="place" data-id="${esc(p.id)}">${icon(glyph(p))}${esc(p.name.replace('（示例）',''))}</button>`).join('')}<button class="quick-item" data-act="favorites">全部收藏　›</button></div></section>`;}
function detailPage(){let p=state.selected,f=favorite(p);return `${mapBase()}<div class="map-top">${deviceChip()}</div>${mapTools()}<section class="sheet"><div class="sheet-grip"></div><div class="sheet-heading"><h2>${esc(p.name)}</h2><button class="icon-btn plain-icon" aria-label="关闭地点详情" data-act="map">${icon('close')}</button></div><p class="sub">${esc(p.group||'地图选点')} · ${f?'已保存在收藏':'尚未收藏'}</p>${p.note?`<p class="detail-note">${esc(p.note)}</p>`:''}<div class="button-row"><button class="primary" data-act="navigate">${icon('route')}${state.searchTarget==='via'?'添加为途经点':state.searchTarget==='origin'?'设为起点':'骑行去这里'}</button><button class="secondary" data-act="edit-selected">${icon(f?'edit':'star')}${f?'编辑':'收藏'}</button></div><div class="detail-secondary"><button data-act="set-origin">设为起点</button><button data-act="add-via">途经这里</button>${f?'<button data-act="delete-selected">删除收藏</button>':'<button data-act="copy-coordinates">复制坐标</button>'}</div><div class="detail-coordinate">${p.lat.toFixed(6)}° N, ${p.lon.toFixed(6)}° E</div></section>`;}
function favoritePage(){return `<section class="screen">${head('收藏','new-favorite','＋ 新建')}<div class="screen-scroll"><div class="field-search">${icon('search')}<input id="favorite-query" placeholder="搜索名称或备注" value="${esc(state.query)}" aria-label="搜索收藏"></div><div class="filters">${['全部',...groups].map(g=>`<button class="filter ${state.filter===g?'selected':''}" data-act="filter" data-group="${g}">${g}</button>`).join('')}</div><div class="section-title"><span id="favorite-count"></span><button data-act="sort">切换排序</button></div><div id="favorite-results"></div><div class="transfer"><button data-act="import">导入 GeoJSON</button><button data-act="export">导出收藏</button><button data-act="map">在地图查看</button></div><p class="tiny">原型数据仅保存在当前浏览器，不会修改手机 App 的收藏。</p></div></section>`;}
function fillFavorites(){const q=state.query.trim().toLowerCase(),items=store.favorites.filter(p=>(state.filter==='全部'||state.filter===p.group)&&[p.name,p.note].join(' ').toLowerCase().includes(q));if(state.sortName)items.sort((a,b)=>a.name.localeCompare(b.name,'zh'));$('#favorite-count').textContent=`${items.length} 个地点 · ${state.sortName?'按名称':'最近保存'}`;$('#favorite-results').innerHTML=items.length?items.map(row).join(''):empty('这里还没有地点','可以搜索地点后收藏，也可以直接在地图上标点。','添加收藏','new-favorite');}
function searchPage(){return `<section class="screen"><header class="screen-head"><button class="icon-btn plain-icon" aria-label="返回" data-act="map">${icon('back')}</button><h2>${state.searchTarget==='via'?'添加途经点':state.searchTarget==='origin'?'选择起点':'查找地点'}</h2></header><div class="screen-scroll"><div class="field-search">${icon('search')}<input id="place-query" placeholder="地点、地址或经纬度" aria-label="查找地点" autocomplete="off"></div><div class="source-row">本地收藏可操作 · 在线搜索仅展示交互示例</div><div id="search-results"></div></div></section>`;}
function fillSearch(){let q=state.query.trim().toLowerCase(),local=store.favorites.filter(p=>[p.name,p.note].join(' ').toLowerCase().includes(q)),sample=samples.filter(p=>!local.some(x=>x.id===p.id)&&[p.name,p.note,p.group].join(' ').toLowerCase().includes(q));let result=`<div class="section-title">${q?'匹配的收藏':'常用与收藏'}</div>${local.length?local.map(row).join(''):'<p class="tiny">没有匹配收藏。</p>'}`;if(q){const xy=q.match(/^\s*([+-]?\d+(?:\.\d+)?)\s*[,，]\s*([+-]?\d+(?:\.\d+)?)\s*$/);if(xy&&Math.abs(+xy[1])<=80&&Math.abs(+xy[2])<=180){state.coordinate={id:'coordinate',name:'坐标选点',lat:+xy[1],lon:+xy[2],group:'其他',note:'来自输入坐标'};result+=`<div class="section-title">坐标结果</div>${row(state.coordinate)}`;}result+=`<div class="section-title">示例搜索结果</div>${sample.length?sample.map(row).join(''):'<p class="tiny">原型不联网搜索。正式版将展示在线结果、地址和明确的失败状态。</p>'}`;}$('#search-results').innerHTML=result;}
function openEditor(p,back='favorites'){state.editing={...p,group:p.group||'其他',color:p.color||colors[0],id:favorite(p)?.id||null};state.editorReturn=back;state.page='editor';render();}
function editorPage(){const p=state.editing;return `<section class="screen"><header class="screen-head"><button class="icon-btn plain-icon" aria-label="取消编辑" data-act="cancel-edit">${icon('back')}</button><h2>${p.id?'编辑收藏':'保存地点'}</h2><button class="text-action" data-act="save-favorite">保存</button></header><form id="favorite-form" class="screen-scroll"><label class="form-field">地点名称<input name="name" value="${esc(p.name||'')}" required maxlength="60" placeholder="例如：周末补水点"></label><label class="form-field">分组<select name="group">${groups.map(g=>`<option ${g===p.group?'selected':''}>${g}</option>`).join('')}</select></label><label class="form-field">备注<textarea name="note" maxlength="500" placeholder="营业时间、停车位置、下次想做的事…">${esc(p.note||'')}</textarea></label><div class="form-pair"><label class="form-field">纬度<input name="lat" inputmode="decimal" value="${p.lat.toFixed(6)}"></label><label class="form-field">经度<input name="lon" inputmode="decimal" value="${p.lon.toFixed(6)}"></label></div><label class="form-field">地图标记颜色</label><div class="color-options">${colors.map(c=>`<button type="button" aria-label="${c}" class="${p.color===c?'selected':''}" style="background:${c}" data-act="color" data-color="${c}"></button>`).join('')}</div><p id="form-error" class="validation" role="alert"></p><p class="tiny">名称、分类与备注可以在收藏中搜索。正式版将保留度分秒坐标输入和地图调整位置。</p></form><footer class="editor-footer"><button class="primary block" data-act="save-favorite">保存到收藏</button></footer></section>`;}
function saveFavorite(){const data=new FormData($('#favorite-form')),name=String(data.get('name')).trim(),lat=Number(data.get('lat')),lon=Number(data.get('lon'));if(!name||name.length>60||!String(data.get('lat')).trim()||!String(data.get('lon')).trim()||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>80||Math.abs(lon)>180){$('#form-error').textContent='请填写地点名称和有效的经纬度。纬度需在 ±80°、经度在 ±180° 内。';return;}const p={...state.editing,id:state.editing.id||id(),name,lat,lon,group:String(data.get('group')),note:String(data.get('note')).trim(),updatedAt:new Date().toISOString()};store.favorites=store.favorites.filter(x=>x.id!==p.id);store.favorites.unshift(p);persist();state.query='';state.filter='全部';state.selected=p;state.page=state.editorReturn==='detail'?'detail':'favorites';render();toast('已保存，可从收藏直接规划路线。');}
function plannerPage(){let d=state.draft;return `${mapBase(true)}<div class="planner-top"><div class="head"><button class="icon-btn plain-icon" aria-label="返回地图" data-act="map">${icon('back')}</button><strong>规划骑行</strong><button class="icon-btn plain-icon" aria-label="交换起终点" data-act="swap">⇅</button></div><div class="point-line"><span></span><button data-act="search-origin">${esc(d.from?.name||'选择起点')}</button></div>${d.via.map((p,i)=>`<div class="point-line via"><span>${i+1}</span><button data-act="via-detail" data-index="${i}">${esc(p.name)}</button><button class="micro" aria-label="上移途经点" data-act="via-up" data-index="${i}" ${i===0?'disabled':''}>↑</button><button class="micro" aria-label="删除途经点" data-act="via-remove" data-index="${i}">×</button></div>`).join('')}<div class="point-line end"><span></span><button data-act="search-destination">${esc(d.to?.name||'选择目的地')}</button></div><div class="planner-meta"><span>自行车</span><span>·</span><span>途经点 ${d.via.length}</span><button data-act="search-via">＋ 添加途经点</button></div></div><section class="sheet"><div class="sheet-grip"></div>${state.ready?`<span class="tag">路线方案示例</span><div class="route-stats"><strong>8.6</strong><span>km</span><span class="eta">约 36 分钟</span></div><p class="sub">预览布局演示。此线仅连接选点，未请求道路规划，不能用于实际导航。</p><div class="button-row"><button class="secondary" data-act="save-route">${icon('star')}保存路线</button><button class="primary" data-act="start-ride">演示骑行界面</button></div><div class="detail-secondary"><button data-act="edit-route">编辑路线</button><button data-act="device">${state.connected?'码表已连接 · 演示':'未连接码表 · 可手机导航'}</button></div>`:`<h2>准备好，再出发</h2><p class="sub">起终点与途经点始终可见，规划完成后先确认路线，再开始骑行。</p><button class="primary block" data-act="plan-demo" ${!d.to?'disabled':''}>预览路线方案（示例）</button>`}</section>`;}
function routePage(){let history=state.routeFilter==='rides',list=history?store.rides:store.routes;return `<section class="screen">${head('路线','new-route','＋ 新建')}<div class="screen-scroll"><div class="segmented"><button class="${!history?'selected':''}" data-act="route-filter" data-value="saved">已保存</button><button class="${history?'selected':''}" data-act="route-filter" data-value="rides">骑行记录</button></div>${list.length?list.map(r=>`<button class="place-row" data-act="${history?'ride-record':'open-route'}" data-id="${r.id}"><span class="route-thumb">${icon('route')}</span><span class="content"><strong>${esc(r.name)}</strong><small>${history?'演示记录 · 不是真实骑行':'示例路线 · '+r.draft.via.length+' 个途经点'}</small><small>${esc(r.created.slice(0,10))}</small></span><span class="chevron">›</span></button>`).join(''):empty(history?'每一程，都可以留下来':'把想骑的路，留到下次',history?'结束骑行后，在这里查看轨迹和记录。演示记录始终单独标记。':'在路线预览中保存，再次出发就不用重新选择地点。',history?'查看骑行演示':'规划一条路线',history?'demo-ride':'new-route')}<p class="tiny" style="margin-top:23px">正式版在此提供 GPX 路线导入、分享和重命名。原型演示路线保存与再次打开。</p></div></section>`;}
function devicePage(){return `<section class="screen">${head('设备')}<div class="screen-scroll"><div class="device-hero">${icon('device')}<h2>${state.connected?'VELO-ESP32':'连接你的码表'}</h2><p class="sub">${state.connected?'已连接 · 这是原型状态演示':'手机负责规划，码表陪你骑行。'}</p><button class="primary block" data-act="connect">${state.connected?'演示断开连接':'查看连接流程'}</button></div><div class="section-title">导航与地图</div><button class="setting-row" data-act="alert"><span class="content"><strong>反向行驶提醒</strong><small>确认持续反向移动后，声音和振动提示</small></span><span class="toggle ${state.alert?'':'off'}"></span></button><button class="setting-row" data-act="board-roads"><span class="content"><strong>码表周边道路</strong><small>手机加载道路，传给码表显示</small></span><span class="toggle ${state.boardRoads?'':'off'}"></span></button><button class="setting-row" data-act="theme"><span class="content"><strong>外观</strong><small>切换浅色与深色演示</small></span><span class="chevron">›</span></button><button class="setting-row" data-act="permissions"><span class="content"><strong>定位与后台运行</strong><small>权限和连接问题各有对应处理入口</small></span><span class="chevron">›</span></button><p class="tiny" style="margin-top:23px">搜索、收藏和规划不以连接码表为前提。设备状态是模拟，不会访问真实蓝牙。</p></div></section>`;}
function ridePage(){return `${mapBase(true)}<div class="ride-banner ${state.wrong?'wrong':''}"><div class="turn-icon">${state.wrong?'↶':'↰'}</div><div><strong>${state.wrong?'方向相反':'80 m'}</strong><small>${state.wrong?'请核对路线，安全时调整方向':'前方路口左转'}</small></div><span class="demo">演示</span></div><button class="ride-state-button" data-act="wrong">${state.wrong?'恢复正常提示':'查看反向提醒状态'}</button><section class="sheet ride-sheet"><p class="ride-notice">${state.paused?'骑行已暂停（演示）':state.connected?'码表已连接（演示）':'手机导航（演示） · 码表未连接'}</p><div class="ride-metrics"><div><strong>${state.paused?'0.0':'18.6'}<span class="unit"> km/h</span></strong><small>当前速度</small></div><div><strong>6.2<span class="unit"> km</span></strong><small>剩余距离</small></div><div><strong>26<span class="unit"> min</span></strong><small>预计剩余</small></div></div><div class="button-row"><button class="secondary" data-act="pause">${icon('pause')}${state.paused?'继续':'暂停'}</button><button class="primary" data-act="end-ride">结束骑行</button></div></section>`;}
function render(){const pages={map:mapPage,detail:detailPage,favorites:favoritePage,search:searchPage,editor:editorPage,planner:plannerPage,routes:routePage,device:devicePage,ride:ridePage};app.innerHTML=(pages[state.page]||mapPage)();let current=['detail','search','planner','ride'].includes(state.page)?'map':state.page==='editor'?'favorites':state.page;nav.innerHTML=[['map','map','地图'],['favorites','star','收藏'],['routes','route','路线'],['device','device','设备']].map(([p,i,t])=>`<button data-act="jump" data-page="${p}" class="${p===current?'active':''}" aria-current="${p===current?'page':'false'}"><span class="nav-icon">${icon(i)}</span>${t}</button>`).join('');if(state.page==='favorites')fillFavorites();if(state.page==='search')fillSearch();const descriptions={map:['地图与地点','地图保持主体，选中地点后，操作集中在底部面板。'],favorites:['收藏是独立功能','检索、分类和备注都在这里，保存后可直接规划。'],editor:['保存一个可复用的地点','地点不只是一对坐标，名称、分组和备注一起保存。'],detail:['同一种地点详情','搜索、地图选点和收藏，使用完全相同的操作。'],search:['先找到，再确认','收藏离线可用，在线搜索失败不等于目的地没选中。'],planner:['规划草稿与路线预览','起终点、途经点和规划结果保持明确对应，保存后再骑行。'],routes:['路线与记录分开','计划骑的路和实际骑过的轨迹，分别管理。'],ride:['专注当前一程','大号转向、清楚的状态与暂停结束，其他操作收起。'],device:['设备不阻挡主流程','没有码表也能搜索、收藏与规划，连接问题单独处理。']};const d=descriptions[state.page]||descriptions.map;$('#flow-title').textContent=d[0];$('#flow-description').textContent=d[1];}
function dialog(title,body,buttons){$('#modal').innerHTML=`<div class="modal-shade"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h3>${esc(title)}</h3>${body}<div class="button-row">${buttons}</div></section></div>`;}
function closeDialog(){$('#modal').innerHTML='';}
function deleteSelected(){const p=favorite(state.selected);if(!p)return;undo={type:'favorite',value:p,index:store.favorites.indexOf(p)};store.favorites=store.favorites.filter(x=>x.id!==p.id);persist();go('favorites');toast('已删除收藏。',true);}
function exportFavorites(){const data={type:'FeatureCollection',features:store.favorites.map(p=>({type:'Feature',id:p.id,geometry:{type:'Point',coordinates:[p.lon,p.lat]},properties:{name:p.name,group:p.group,note:p.note,color:p.color}}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=url;a.download='VELO-原型收藏.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已导出浏览器原型收藏。');}
function importFavorites(){const input=document.createElement('input');input.type='file';input.accept='.json,.geojson';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('请导入 2 MB 以内的地点文件。');const data=JSON.parse(await file.text());if(data.type!=='FeatureCollection'||!Array.isArray(data.features)||data.features.length>1000)throw Error('需要包含至多 1000 个地点的 GeoJSON FeatureCollection。');const incoming=data.features.map(f=>{const c=f.geometry?.coordinates,p=f.properties||{};if(f.geometry?.type!=='Point'||!Array.isArray(c)||c.length<2||typeof c[0]!=='number'||typeof c[1]!=='number'||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>80)throw Error('文件包含无效或非地点坐标，未导入任何数据。');return{id:String(f.id||id()),name:String(p.name||'导入地点').slice(0,60),group:groups.includes(p.group)?p.group:'其他',note:String(p.note||'').slice(0,500),color:colors.includes(p.color)?p.color:colors[0],lon:c[0],lat:c[1]};});const known=new Set(store.favorites.map(p=>p.id)),fresh=incoming.filter(p=>{if(known.has(p.id))return false;known.add(p.id);return true;});dialog('导入收藏',`<p>文件中有 ${incoming.length} 个地点，其中 ${fresh.length} 个为新地点。重复 ID 保留原有收藏，不覆盖你的编辑。</p>`,`<button class="secondary" data-act="close-dialog">取消</button><button class="primary" id="confirm-import">确认导入</button>`);$('#confirm-import').onclick=()=>{store.favorites.unshift(...fresh);persist();closeDialog();go('favorites');toast(`已导入 ${fresh.length} 个地点。`);};}catch(e){toast(e.message||'文件读取失败，原有收藏未变更。');}};input.click();}
function routeDraftChanged(){state.ready=false;state.page='planner';render();}
document.addEventListener('input',e=>{if(e.target.id==='favorite-query'){state.query=e.target.value;fillFavorites();}if(e.target.id==='place-query'){state.query=e.target.value;fillSearch();}});
document.addEventListener('submit',e=>{if(e.target.id==='favorite-form'){e.preventDefault();saveFavorite();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const action=b.dataset.act,p=state.selected;
switch(action){
case'jump':go(b.dataset.page);break;case'map':state.searchTarget='destination';go('map');break;case'favorites':go('favorites');break;case'device':go('device');break;
case'search':case'search-destination':case'search-origin':case'search-via':state.searchTarget=action==='search-origin'?'origin':action==='search-via'?'via':'destination';go('search');break;
case'place':case'map-pin':selectPlace(store.favorites.find(x=>x.id===b.dataset.id)||samples.find(x=>x.id===b.dataset.id)||(state.coordinate?.id===b.dataset.id?state.coordinate:null));break;
case'drop':selectPlace({id:'map-point',name:'地图选点',...center,group:'其他',note:''});break;
case'locate':toast('已回到示例位置。正式版会定位到手机当前位置。');break;
case'layers':state.showPins=!state.showPins;render();toast(state.showPins?'地图已显示收藏。':'地图已隐藏收藏。');break;
case'new-favorite':openEditor({...center,name:'',group:'其他',note:''},'favorites');break;
case'edit-selected':openEditor(p,'detail');break;
case'cancel-edit':state.page=state.editorReturn==='detail'&&state.selected?'detail':'favorites';render();break;
case'color':state.editing.color=b.dataset.color;document.querySelectorAll('.color-options button').forEach(x=>x.classList.toggle('selected',x===b));break;
case'save-favorite':saveFavorite();break;
case'filter':state.filter=b.dataset.group;render();break;
case'sort':state.sortName=!state.sortName;fillFavorites();break;
case'delete-selected':deleteSelected();break;
case'undo':if(undo?.type==='favorite'){store.favorites.splice(undo.index,0,undo.value);persist();undo=null;go('favorites');toast('已恢复收藏。');}break;
case'navigate':if(state.searchTarget==='origin')state.draft.from={...p};else if(state.searchTarget==='via')state.draft.via.push({...p});else state.draft.to={...p};state.searchTarget='destination';routeDraftChanged();break;
case'set-origin':state.draft.from={...p};routeDraftChanged();break;
case'add-via':state.draft.via.push({...p});routeDraftChanged();break;
case'copy-coordinates':if(navigator.clipboard)navigator.clipboard.writeText(`${p.lat}, ${p.lon}`).then(()=>toast('坐标已复制。')).catch(()=>toast(`${p.lat}, ${p.lon}`));else toast(`${p.lat}, ${p.lon}`);break;
case'new-route':state.draft={from:{...center,name:'当前位置（示例）'},to:null,via:[]};routeDraftChanged();break;
case'swap':if(state.draft.to){[state.draft.from,state.draft.to]=[state.draft.to,state.draft.from];routeDraftChanged();}else toast('请先选择目的地。');break;
case'via-remove':state.draft.via.splice(+b.dataset.index,1);routeDraftChanged();break;
case'via-up':{let i=+b.dataset.index;if(i>0)[state.draft.via[i-1],state.draft.via[i]]=[state.draft.via[i],state.draft.via[i-1]];routeDraftChanged();break;}
case'via-detail':selectPlace(state.draft.via[+b.dataset.index]);break;
case'plan-demo':state.ready=true;render();toast('展示路线预览布局，未执行真实道路规划。');break;
case'edit-route':state.ready=false;render();break;
case'save-route':dialog('保存路线','<label class="tiny" for="route-name">路线名称</label><input id="route-name" maxlength="60" value="'+esc(state.draft.to?.name||'我的路线')+'">','<button class="secondary" data-act="close-dialog">取消</button><button class="primary" data-act="confirm-save-route">保存</button>');break;
case'confirm-save-route':{let name=$('#route-name').value.trim();if(!name){$('#route-name').focus();return;}store.routes.unshift({id:id(),name,created:new Date().toISOString(),draft:structuredClone(state.draft)});persist();closeDialog();go('routes');state.routeFilter='saved';render();toast('示例路线已保存，重新打开原型仍可查看。');break;}
case'route-filter':state.routeFilter=b.dataset.value;render();break;
case'open-route':{const r=store.routes.find(x=>x.id===b.dataset.id);if(r){state.draft=structuredClone(r.draft);state.ready=true;state.page='planner';render();}break;}
case'start-ride':case'demo-ride':state.page='ride';state.paused=false;state.wrong=false;render();toast('骑行界面演示，不读取位置，也不发送到码表。');break;
case'pause':state.paused=!state.paused;render();break;case'wrong':state.wrong=!state.wrong;render();break;
case'end-ride':dialog('结束本次演示骑行？','<p>正式版会在这里保存真实骑行轨迹。原型仅保存一条带演示标记的记录。</p>','<button class="secondary" data-act="discard-ride">不保存</button><button class="primary" data-act="save-ride">结束并保存</button>');break;
case'discard-ride':closeDialog();go('map');break;
case'save-ride':store.rides.unshift({id:id(),name:'骑行界面演示记录',created:new Date().toISOString()});persist();closeDialog();state.routeFilter='rides';go('routes');break;
case'ride-record':dialog('演示记录','<p>仅用于验证“结束 → 保存 → 骑行记录”的流程，不包含实际定位轨迹，不计入真实骑行统计。</p>','<button class="primary block" data-act="close-dialog">知道了</button>');break;
case'connect':if(state.connected){state.connected=false;render();toast('已演示断开连接。');}else dialog('连接码表','<p>正式版将在这里检查蓝牙权限、列出已配对的码表，并说明连接失败原因。</p><p>当前是交互原型，不会访问手机或电脑的蓝牙。</p>','<button class="secondary" data-act="close-dialog">取消</button><button class="primary" data-act="demo-connect">演示已连接</button>');break;
case'demo-connect':state.connected=true;closeDialog();render();toast('连接状态演示，不是真实蓝牙连接。');break;
case'alert':state.alert=!state.alert;render();break;case'board-roads':state.boardRoads=!state.boardRoads;render();break;
case'permissions':dialog('定位与后台运行','<p>正式版分别显示定位、附近设备、通知和后台运行状态。点击缺失项目直接处理，不要求先连接码表才能使用地图。</p>','<button class="primary block" data-act="close-dialog">知道了</button>');break;
case'theme':document.querySelector('.phone').classList.toggle('night');break;
case'export':exportFavorites();break;case'import':importFavorites();break;case'close-dialog':closeDialog();break;
case'reset':dialog('恢复原型示例？','<p>只重置此浏览器里的原型收藏、路线和演示记录，不影响手机 App。</p>','<button class="secondary" data-act="close-dialog">取消</button><button class="primary" data-act="confirm-reset">恢复示例</button>');break;
case'confirm-reset':store={favorites:structuredClone(samples),routes:[],rides:[]};persist();closeDialog();state.draft={from:{...center,name:'当前位置（示例）'},to:null,via:[]};state.ready=false;state.filter='全部';go('map');toast('原型示例已恢复。');break;
}
});
let down=null;document.addEventListener('pointerdown',e=>{if(e.target.closest('#map-canvas')&&!e.target.closest('[data-act]'))down={x:e.clientX,y:e.clientY,time:Date.now()};});document.addEventListener('pointerup',e=>{if(!down)return;const d=down;down=null;if(Math.hypot(e.clientX-d.x,e.clientY-d.y)>10||Date.now()-d.time<450)return;const svg=$('#map-canvas');if(!svg)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());selectPlace({id:'map-point',name:'地图选点',lat:center.lat+(360-p.y)/(.55*111195),lon:center.lon+(p.x-210)/(.55*111195*Math.cos(center.lat*Math.PI/180)),group:'其他',note:''});});
render();
})();
